CREATE TEMP TABLE s503c_cards (id bigint, s_ed text, s_book text, src_ch int, src_vn int, src_text text, t_ed text, tgt_book text, tgt_ch int, tgt_vn int, old_note text, new_note text, thread_id bigint, old_mnote text, new_mnote text) ON COMMIT DROP;
INSERT INTO s503c_cards VALUES
(121850,'canon','matthew',8,11,$n$And I say unto you, That many shall come from the east and west, and shall sit down with Abraham, and Isaac, and Jacob, in the kingdom of heaven.$n$,'canon','isaiah',25,6,$n$*And in this mountain shall Yahuah Tseva'ot (LORD of hosts) make unto all people a feast of fat things, a feast of wines on the lees, of fat things full of marrow, of wines on the lees well refined* (Isaiah 25:6). *Many shall come from the east and west, and shall sit down with Abraham, and Isaac, and Jacob* — this is that mountain feast for all people.$n$,$n$Isaiah 25:6 — *And in this mountain shall Yahuah Tseva'ot (LORD of hosts) make unto all people a feast of fat things, a feast of wines on the lees, of fat things full of marrow, of wines on the lees well refined.* *And I say unto you, That many shall come from the east and west, and shall sit down with Abraham, and Isaac, and Jacob, in the kingdom of heaven.* (Matthew 8:11) The many who sit down with Abraham sit down at this table. Isaiah set the feast on the mountain and spread it *unto all people*, and the ones Yahusha (Jesus) says will come to it come *from the east and west*, the directions the prophets give for the scattered coming home. The feast is the gathering's table, laid before the gathering began.$n$,30423,$n$Isaiah 25:6 — *a feast of fat things... unto all people* — the mountain feast the gathered sit down to.$n$,$n$Isaiah 25:6 — *make unto all people a feast of fat things.* The mountain feast of fat things is the table the many from east and west sit down to with the fathers.$n$),
(2547,'canon','matthew',8,11,$n$And I say unto you, That many shall come from the east and west, and shall sit down with Abraham, and Isaac, and Jacob, in the kingdom of heaven.$n$,'canon','isaiah',49,12,$n$*Behold, these shall come from far: and, lo, these from the north and from the west; and these from the land of Sinim* — the directional-formula of the gathering.$n$,$n$Isaiah 49:12 — *Behold, these shall come from far: and, lo, these from the north and from the west; and these from the land of Sinim.* *And I say unto you, That many shall come from the east and west, and shall sit down with Abraham, and Isaac, and Jacob, in the kingdom of heaven.* (Matthew 8:11) Isaiah's *these shall come from far* is said of the people Yahuah (the LORD) is bringing back, named by the quarters they come from: the north, the west, the land of Sinim. Yahusha (Jesus) gives the same directions for the many who will sit with Abraham. The compass points are not a figure for the nations; they are where the house was scattered to.$n$,30423,$n$Isaiah 49:12 — *these shall come from far... from the north and from the west* — the scattered drawn home.$n$,$n$Isaiah 49:12 — *Behold, these shall come from far: and, lo, these from the north and from the west; and these from the land of Sinim.* These from far, from the north and the west and the land of Sinim: the scattered named by the quarters they return from.$n$),
(121852,'canon','matthew',8,11,$n$And I say unto you, That many shall come from the east and west, and shall sit down with Abraham, and Isaac, and Jacob, in the kingdom of heaven.$n$,'canon','psalms',107,3,$n$*And gathered them out of the lands, from the east, and from the west, from the north, and from the south* (Psalm 107:3). The redeemed of Yahuah brought in from the four winds — scattered Yashar'el coming home and the stranger grafted in.$n$,$n$Psalm 107:3 — *And gathered them out of the lands, from the east, and from the west, from the north, and from the south.* *And I say unto you, That many shall come from the east and west, and shall sit down with Abraham, and Isaac, and Jacob, in the kingdom of heaven.* (Matthew 8:11) The psalm says who is gathered *from the east, and from the west*, and from the north and the south too: the redeemed of Yahuah (the LORD), *whom he hath redeemed from the hand of the enemy* (Psalm 107:2). The many who come from east and west to sit with the fathers are those redeemed, gathered out of the lands they were driven into. Not strangers added to the house; the house brought home.$n$,30423,$n$Psalm 107:3 — *gathered them out of the lands, from the east, and from the west* — the four-winds ingathering.$n$,$n$Psalm 107:3 — *And gathered them out of the lands, from the east, and from the west, from the north, and from the south.* The redeemed gathered out of the lands from all four quarters: the many from east and west are the house coming home.$n$),
(121853,'canon','matthew',8,11,$n$And I say unto you, That many shall come from the east and west, and shall sit down with Abraham, and Isaac, and Jacob, in the kingdom of heaven.$n$,'canon','malachi',1,11,$n$*For from the rising of the sun even unto the going down of the same my name shall be great among the Gentiles; and in every place incense shall be offered unto my name, and a pure offering: for my name shall be great among the heathen, saith Yahuah Tseva'ot (LORD of hosts)* (Malachi 1:11). The nations brought near — the centurion is the firstfruit.$n$,$n$Malachi 1:11 — *For from the rising of the sun even unto the going down of the same my name shall be great among the Gentiles; and in every place incense shall be offered unto my name, and a pure offering: for my name shall be great among the heathen, saith Yahuah Tseva'ot (LORD of hosts).* *And I say unto you, That many shall come from the east and west, and shall sit down with Abraham, and Isaac, and Jacob, in the kingdom of heaven.* (Matthew 8:11) Malachi hears that the name will be great *among the Gentiles* from the sun's rising to its going down, with a pure offering in every place. The centurion is a man in whom that was already so, a Roman who loved the nation and built its synagogue, and who trusted the word. Where the scattered went, the name went with them, and the many from east and west come back from those same places.$n$,30423,$n$Malachi 1:11 — *my name shall be great among the Gentiles* — the centurion is the firstfruit.$n$,$n$Malachi 1:11 — *my name shall be great among the Gentiles.* The name great among the Gentiles from sunrise to sunset: the name carried by the scattered where they were driven, and a centurion who had it.$n$),
(121854,'canon','matthew',8,12,$n$But the children of the kingdom shall be cast out into outer darkness: there shall be weeping and gnashing of teeth.$n$,'canon','romans',11,1,$n$*I say then, Hath Elohim (God) cast away his people? Elohim (God) forbid. For I also am an Israelite, of the seed of Abraham, of the tribe of Benjamin* (Romans 11:1). *The children of the kingdom cast out* is INDIVIDUAL unbelief, never the casting off of Yashar'el as a people — read it through this guard.$n$,$n$Romans 11:1 — *I say then, Hath Elohim (God) cast away his people? Elohim (God) forbid. For I also am an Israelite, of the seed of Abraham, of the tribe of Benjamin.* *But the children of the kingdom shall be cast out into outer darkness: there shall be weeping and gnashing of teeth.* (Matthew 8:12) *The children of the kingdom shall be cast out* has been read as the house of Yashar'el (Israel) put away for the nations. Paul answers that reading before it starts: *Hath Elohim (God) cast away his people? Elohim (God) forbid*, and offers himself, of the seed of Abraham, as the proof. The casting out here is the sifting of the house, the unhearing thrust out while the gathered sit down; the house itself is not cast away.$n$,30423,$n$Romans 11:1 — *Hath Elohim (God) cast away his people? Elohim (God) forbid* — the guard on verse 12: unbelief, not the nation.$n$,$n$Romans 11:1 — *Hath Elohim (God) cast away his people? Elohim (God) forbid.* Has Elohim (God) cast away his people? Elohim (God) forbid: the guard on the children of the kingdom cast out.$n$),
(121855,'canon','matthew',8,12,$n$But the children of the kingdom shall be cast out into outer darkness: there shall be weeping and gnashing of teeth.$n$,'canon','romans',11,2,$n$*Elohim (God) hath not cast away his people which he foreknew* (Romans 11:2). The warning of verse 12 falls on the unbelieving heart, not on the nation; the feast GAINS the believing stranger, it does not disinherit Israel.$n$,$n$Romans 11:2 — *Elohim (God) hath not cast away his people which he foreknew. Wot ye not what the scripture saith of Elijah? how he maketh intercession to Elohim (God) against Yashar'el (Israel), saying,* *But the children of the kingdom shall be cast out into outer darkness: there shall be weeping and gnashing of teeth.* (Matthew 8:12) The ones cast out into outer darkness are children of the kingdom who would not hear, not the people Elohim (God) foreknew. Paul says it in one line: he *hath not cast away his people which he foreknew*. The weeping at the door is the sifting of the house, some thrust out while the fathers and the gathered sit down, and the people as a people stand where they stood.$n$,30423,$n$Romans 11:2 — *Elohim (God) hath not cast away his people which he foreknew* — Israel never replaced.$n$,$n$Romans 11:2 — *Elohim (God) hath not cast away his people which he foreknew.* Not cast away, the people he foreknew: the casting out at the feast is of the unhearing, not of the house.$n$),
(5513,'canon','matthew',8,11,$n$And I say unto you, That many shall come from the east and west, and shall sit down with Abraham, and Isaac, and Jacob, in the kingdom of heaven.$n$,'canon','luke',13,29,$n$thread:gather-all-the-tribes-of-jacob-in-sirach-and-enoch | The four-direction gathering parallel — *they shall come from the east, and from the west, and from the north, and from the south, and shall sit down in the kingdom of Elohim.*$n$,$n$Luke 13:29 — *And they shall come from the east, and from the west, and from the north, and from the south, and shall sit down in the kingdom of Elohim (God).* *And I say unto you, That many shall come from the east and west, and shall sit down with Abraham, and Isaac, and Jacob, in the kingdom of heaven.* (Matthew 8:11) Luke sets the same gathering after the question whether few are saved, and adds the two quarters Matthew leaves out, the north and the south: all four directions to the one table, the kingdom of Elohim (God). Beside it Luke keeps the other half of Matthew's saying too, the ones at home who see the fathers seated *and you yourselves thrust out* (Luke 13:28). The gathering and the sifting stand together in both gospels.$n$,30423,$n$Luke 13:29 — *they shall come from the east, and from the west... and shall sit down in the kingdom* — the same gathering.$n$,$n$Luke 13:29 — *And they shall come from the east, and from the west, and from the north, and from the south, and shall sit down in the kingdom of Elohim (God).* From all four quarters to the kingdom of Elohim (God): Luke's telling of the same gathering, with the sifting beside it.$n$);
CREATE TEMP TABLE s503c_thread (id bigint, slug text, old_title text, new_title text, old_summary text, new_summary text) ON COMMIT DROP;
INSERT INTO s503c_thread VALUES (30423, 'matthew-8-many-from-east-and-west-sit-with-abraham-isaiah-25-malachi-1', $n$Many shall come from east and west to the feast with Abraham (Isaiah 25; Malachi 1; Romans 11)$n$, $n$Many shall come from the east and west and sit down with Abraham — the centurion who heard, and the house gathered from every quarter (Isaiah 11; Psalm 107; Luke 13)$n$, $n$A Roman centurion — a Gentile soldier — believes that a word at a distance can heal, and Yahusha (Jesus) marvels: *I have not found so great faith, no, not in Yashar'el (Israel).* Then He opens the table: *many shall come from the east and west, and shall sit down with Abraham, and Isaac, and Jacob, in the kingdom of heaven.* This is the mountain feast of the prophets — *And in this mountain shall Yahuah Tseva'ot (LORD of hosts) make unto all people a feast of fat things* (Isaiah 25:6) — the scattered drawn home from every quarter: *Behold, these shall come from far: and, lo, these from the north and from the west* (Isaiah 49:12), *gathered... from the east, and from the west, from the north, and from the south* (Psalm 107:3), so that *from the rising of the sun even unto the going down of the same my name shall be great among the Gentiles* (Malachi 1:11). Luke sings the same: *they shall come from the east, and from the west... and shall sit down in the kingdom of Elohim (God)* (Luke 13:29). But hear the warning rightly — *the children of the kingdom shall be cast out* is individual unbelief, NOT the casting off of the nation. *Hath Elohim (God) cast away his people? Elohim (God) forbid* (Romans 11:1); *Elohim (God) hath not cast away his people which he foreknew* (Romans 11:2). The feast GAINS the believing stranger and gathers scattered Yashar'el home — it never disinherits Israel.$n$, $n$It ain't new. A centurion in Capernaum asks for a word and not a visit, and Yahusha (Jesus) marvels:

*When Yahusha (Jesus) heard it, he marvelled, and said to them that followed, Verily I say unto you, I have not found so great faith, no, not in Yashar'el (Israel).* (Matthew 8:10)

Not in Yashar'el (Israel) means not in the house at home. Luke tells who this soldier was before he ever sent for him:

*For he loveth our nation, and he hath built us a synagogue.* (Luke 7:5)

A Roman officer who loved the nation and built its synagogue, who called himself unworthy of a visit and trusted the word alone. The sheep hear the voice because they are sheep:

*My sheep hear my voice, and I know them, and they follow me:* (John 10:27)

That is how the man reads: not a stranger whose faith shames the house, but one of the house found out among the nations, known by his hearing. And it is why the next words are about a gathering and not about a replacing:

*And I say unto you, That many shall come from the east and west, and shall sit down with Abraham, and Isaac, and Jacob, in the kingdom of heaven.* (Matthew 8:11)

The prophets had already said who comes from the east and the west, and from where:

*And he shall set up an ensign for the nations, and shall assemble the outcasts of Yashar'el (Israel), and gather together the dispersed of Yahudah (Judah) from the four corners of the earth.* (Isaiah 11:12)

*And gathered them out of the lands, from the east, and from the west, from the north, and from the south.* (Psalm 107:3)

*Behold, these shall come from far: and, lo, these from the north and from the west; and these from the land of Sinim.* (Isaiah 49:12)

The ones gathered are the outcasts and the dispersed, the two houses brought back from every quarter. The table they sit at is the feast the prophet set on the mountain:

*And in this mountain shall Yahuah Tseva'ot (LORD of hosts) make unto all people a feast of fat things, a feast of wines on the lees, of fat things full of marrow, of wines on the lees well refined.* (Isaiah 25:6)

And the name made great in every place is the name carried by the scattered where they were driven:

*For from the rising of the sun even unto the going down of the same my name shall be great among the Gentiles; and in every place incense shall be offered unto my name, and a pure offering: for my name shall be great among the heathen, saith Yahuah Tseva'ot (LORD of hosts).* (Malachi 1:11)

Then the hard word:

*But the children of the kingdom shall be cast out into outer darkness: there shall be weeping and gnashing of teeth.* (Matthew 8:12)

This is not the house put away for the nations. It is the sifting of the house: the ones who had the kingdom in hand and would not do the Father's will, thrust out while the fathers and the gathered sit down. Luke keeps the same scene with the same two halves:

*There shall be weeping and gnashing of teeth, when ye shall see Abraham, and Isaac, and Jacob, and all the prophets, in the kingdom of Elohim (God), and you yourselves thrust out.* (Luke 13:28)

*And they shall come from the east, and from the west, and from the north, and from the south, and shall sit down in the kingdom of Elohim (God).* (Luke 13:29)

And Paul closes the door on the misreading:

*I say then, Hath Elohim (God) cast away his people? Elohim (God) forbid. For I also am an Israelite, of the seed of Abraham, of the tribe of Benjamin.* (Romans 11:1)

A centurion heard, and the house was not cast away. The feast fills with the scattered coming home from every direction, and empties of the ones at home who would not hear.$n$);

DO $s503c$
DECLARE r record; x record; n int;
BEGIN
  FOR r IN SELECT * FROM s503c_cards LOOP
    SELECT xr.id, xr.note, sv.text AS stext, se.slug AS sed, sb.slug AS sbook, sc.chapter_number AS sch, sv.verse_number AS svn, te.slug AS ted, tb.slug AS tbook, tc.chapter_number AS tch, tv.verse_number AS tvn
      INTO x FROM cross_references xr
      JOIN verses sv ON sv.id = xr.source_verse_id JOIN chapters sc ON sc.id = sv.chapter_id JOIN books sb ON sb.id = sc.book_id JOIN editions se ON se.id = sb.edition_id
      JOIN verses tv ON tv.id = xr.target_verse_id JOIN chapters tc ON tc.id = tv.chapter_id JOIN books tb ON tb.id = tc.book_id JOIN editions te ON te.id = tb.edition_id
      WHERE xr.id = r.id;
    IF NOT FOUND THEN RAISE EXCEPTION 'S503c: card % is gone', r.id; END IF;
    IF x.sed <> r.s_ed OR x.sbook <> r.s_book OR x.sch <> r.src_ch OR x.svn <> r.src_vn OR x.ted <> r.t_ed OR x.tbook <> r.tgt_book OR x.tch <> r.tgt_ch OR x.tvn <> r.tgt_vn THEN
      RAISE EXCEPTION 'S503c: card % no longer sits on the verse pair this was written for', r.id; END IF;
    IF x.stext <> r.src_text THEN RAISE EXCEPTION 'S503c: live text of % %:% differs from the read-back — re-dump and rebuild', r.s_book, r.src_ch, r.src_vn; END IF;
    IF x.note IS DISTINCT FROM r.old_note AND x.note IS DISTINCT FROM r.new_note THEN RAISE EXCEPTION 'S503c: the live note of card % differs from the read-back — re-dump and rebuild', r.id; END IF;
    SELECT count(*) INTO n FROM cross_reference_thread_members m WHERE m.cross_reference_id = r.id AND m.thread_id = r.thread_id AND (m.member_note IS NOT DISTINCT FROM r.old_mnote OR m.member_note IS NOT DISTINCT FROM r.new_mnote);
    IF n <> 1 THEN RAISE EXCEPTION 'S503c: card % has no member row in thread % carrying the member note this was written against', r.id, r.thread_id; END IF;
  END LOOP;
  SELECT t.* INTO x FROM cross_reference_threads t JOIN s503c_thread s ON s.id = t.id AND s.slug = t.slug;
  IF NOT FOUND THEN RAISE EXCEPTION 'S503c: thread 30423 not found under its slug'; END IF;
  SELECT count(*) INTO n FROM cross_reference_threads t JOIN s503c_thread s ON s.id = t.id
    WHERE (t.title = s.old_title AND t.summary_md = s.old_summary) OR (t.title = s.new_title AND t.summary_md = s.new_summary);
  IF n <> 1 THEN RAISE EXCEPTION 'S503c: thread 30423 title/summary differ from the read-back — re-dump and rebuild'; END IF;
END $s503c$;

DO $s503c2$
DECLARE n_notes int; n_m int; n_t int; n_c int;
BEGIN
  SELECT count(*) INTO n_c FROM s503c_cards;
  UPDATE cross_references xr SET note = c.new_note FROM s503c_cards c WHERE xr.id = c.id AND xr.note IS NOT DISTINCT FROM c.old_note AND c.old_note IS DISTINCT FROM c.new_note;
  GET DIAGNOSTICS n_notes = ROW_COUNT;
  UPDATE cross_reference_thread_members m SET member_note = c.new_mnote FROM s503c_cards c WHERE m.cross_reference_id = c.id AND m.thread_id = c.thread_id AND m.member_note IS NOT DISTINCT FROM c.old_mnote AND c.old_mnote IS DISTINCT FROM c.new_mnote;
  GET DIAGNOSTICS n_m = ROW_COUNT;
  UPDATE cross_reference_threads t SET title = s.new_title, summary_md = s.new_summary FROM s503c_thread s WHERE t.id = s.id AND t.title = s.old_title AND t.summary_md = s.old_summary;
  GET DIAGNOSTICS n_t = ROW_COUNT;
  RAISE NOTICE 'S503c (matthew-8-many-from) summary: notes rewritten % / already there %; member notes rewritten % / already there %; thread rewritten % / already there %', n_notes, n_c - n_notes, n_m, n_c - n_m, n_t, 1 - n_t;
END $s503c2$;
COMMIT;
\echo 'session503c — matthew-8-many-from done.'
